ALTER TABLE products ADD COLUMN version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), ADD COLUMN short_description TEXT NOT NULL DEFAULT '', ADD COLUMN content_blocks JSONB NOT NULL DEFAULT '[]', ADD COLUMN seo_title TEXT NOT NULL DEFAULT '', ADD COLUMN seo_description TEXT NOT NULL DEFAULT '';
ALTER TABLE brands ADD COLUMN status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive'));
ALTER TABLE categories ADD COLUMN description TEXT NOT NULL DEFAULT '', ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE media_assets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,storage_key TEXT UNIQUE NOT NULL,mime_type TEXT NOT NULL,size_bytes BIGINT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,alt_text TEXT NOT NULL,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE product_media ADD COLUMN alt_text TEXT NOT NULL DEFAULT '';
ALTER TABLE product_variants ADD COLUMN combination_key TEXT;
CREATE UNIQUE INDEX variant_combination_unique ON product_variants(product_id,combination_key) WHERE combination_key IS NOT NULL;
CREATE TABLE seo_redirects(old_path TEXT PRIMARY KEY,new_path TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(old_path<>new_path));
INSERT INTO permissions(code) VALUES ('catalog.create'),('catalog.edit'),('catalog.publish'),('catalog.archive'),('media.read'),('media.upload') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='admin' OR (r.name='content' AND p.code IN ('catalog.create','catalog.edit','catalog.publish','catalog.archive','media.read','media.upload')) ON CONFLICT DO NOTHING;
